using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using RoadGunner;using RoadGunner.ConceptArt.Editor;
public static class InstallVehiclePass {public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");ArtKit.Ensure();string path="Assets/RoadGunner/Prefabs/Dust Jackal.prefab";var p=PrefabUtility.LoadPrefabContents(path);try{ConceptVehicle.Apply(p);PrefabUtility.SaveAsPrefabAsset(p,path);}finally{PrefabUtility.UnloadPrefabContents(p);}AssetDatabase.SaveAssets();var scene=EditorSceneManager.OpenScene("Assets/RoadGunner/Scenes/Level01_Greenwood.unity");var s=UnityEngine.Object.FindAnyObjectByType<GameSession>();s.health.bodyPanels=s.vehicle.GetComponentsInChildren<Renderer>(true).Where(r=>r.name=="Finished shared visuals"&&r.transform.parent.name.Contains("Body and open cargo bed")).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(s.health);EditorSceneManager.SaveScene(scene);return "Player shared prefab and scene body flash renderer updated. "+s.health.bodyPanels.Length+" body renderers.";}}
